python3 -c "
import json, sys

with open('BellevueWeather/BellevueWeather/BellevueWeather.flow') as f:
    flow = json.load(f)

nodes = {n['id']: n for n in flow['nodes']}
edges = flow['edges']

print('=== NODES ===')
for nid, n in nodes.items():
    print(f'  {nid} ({n[\"type\"]})')

print()
print('=== EDGES ===')
for e in edges:
    src = e['sourceNodeId']
    tgt = e['targetNodeId']
    port = e.get('sourcePort', '?')
    ok_src = src in nodes
    ok_tgt = tgt in nodes
    status = '✓' if (ok_src and ok_tgt) else '✗ BROKEN'
    print(f'  {status}  {src}:{port} -> {tgt}')

print()
print('=== VALIDATION ===')
errors = []

# Check all edge refs resolve
for e in edges:
    if e['sourceNodeId'] not in nodes:
        errors.append(f'Edge {e[\"id\"]}: unknown source {e[\"sourceNodeId\"]}')
    if e['targetNodeId'] not in nodes:
        errors.append(f'Edge {e[\"id\"]}: unknown target {e[\"targetNodeId\"]}')

# Check formatSummary script references checkTemperature.matchedCaseId
fs = nodes['formatSummary']
script = fs['inputs']['script']
if 'checkTemperature.matchedCaseId' in script:
    print('  ✓ formatSummary script reads checkTemperature.matchedCaseId')
else:
    errors.append('formatSummary script does not reference checkTemperature.matchedCaseId')

# Check decision expression references getWeather (not formatSummary)
ct = nodes['checkTemperature']
expr = ct['inputs']['expression']
if 'getWeather' in expr and 'formatSummary' not in expr:
    print('  ✓ checkTemperature expression reads from getWeather directly')
else:
    errors.append(f'checkTemperature expression looks wrong: {expr}')

# Check there is exactly one end node
end_nodes = [n for n in nodes.values() if n['type'] == 'core.control.end']
if len(end_nodes) == 1:
    print(f'  ✓ Single end node: {end_nodes[0][\"id\"]}')
else:
    errors.append(f'Expected 1 end node, found {len(end_nodes)}')

# Check both branches of decision lead to formatSummary
true_edges  = [e for e in edges if e['sourceNodeId'] == 'checkTemperature' and e['sourcePort'] == 'true']
false_edges = [e for e in edges if e['sourceNodeId'] == 'checkTemperature' and e['sourcePort'] == 'false']
if true_edges and true_edges[0]['targetNodeId'] == 'formatSummary':
    print('  ✓ True branch -> formatSummary')
else:
    errors.append('True branch does not lead to formatSummary')
if false_edges and false_edges[0]['targetNodeId'] == 'formatSummary':
    print('  ✓ False branch -> formatSummary')
else:
    errors.append('False branch does not lead to formatSummary')

# Check formatSummary leads to end
fmt_edges = [e for e in edges if e['sourceNodeId'] == 'formatSummary']
if fmt_edges and fmt_edges[0]['targetNodeId'] == 'end':
    print('  ✓ formatSummary -> end')
else:
    errors.append('formatSummary does not lead to end')

# Check layout nodes match actual nodes
layout_keys = set(flow['layout']['nodes'].keys())
node_keys = set(nodes.keys())
if layout_keys == node_keys:
    print(f'  ✓ Layout keys match node ids: {sorted(layout_keys)}')
else:
    errors.append(f'Layout mismatch: layout={sorted(layout_keys)}, nodes={sorted(node_keys)}')

# Check variable bindings
var_node_ids = {v['binding']['nodeId'] for v in flow['variables']['nodes']}
expected_var_nodes = {'getWeather', 'checkTemperature', 'formatSummary'}
if expected_var_nodes == var_node_ids:
    print(f'  ✓ Variable bindings reference correct nodes: {sorted(var_node_ids)}')
else:
    errors.append(f'Variable binding nodes: {sorted(var_node_ids)}, expected {sorted(expected_var_nodes)}')

print()
if errors:
    print('ERRORS:')
    for e in errors:
        print(f'  ✗ {e}')
    sys.exit(1)
else:
    print('ALL VALIDATIONS PASSED')
"

